/** The chain, as the reward verifier reads it (server/dailyReward.ts): plain JSON-RPC reads through viem. */
var EVENTS = [
	"Caught",
	"LocationUnlocked",
	"RodBought"
];
var TOPICS = fishingGameAbi.filter((x) => x.type === "event" && EVENTS.includes(x.name)).map((e) => toEventSelector(e));
function chainFacts(opts) {
	const client = createPublicClient({ transport: http(opts.rpcUrl, {
		timeout: opts.timeoutMs ?? 8e3,
		retryCount: 1
	}) });
	const game = {
		address: opts.game,
		abi: fishingGameAbi
	};
	const rewards = {
		address: opts.rewards,
		abi: dailyRewardsAbi
	};
	return {
		async head() {
			const b = await client.getBlock({ blockTag: "latest" });
			return {
				number: b.number,
				timestamp: Number(b.timestamp)
			};
		},
		async timestamp(block) {
			return Number((await client.getBlock({ blockNumber: block })).timestamp);
		},
		async events(player, from, to) {
			const logs = await client.request({
				method: "eth_getLogs",
				params: [{
					address: opts.game,
					fromBlock: `0x${from.toString(16)}`,
					toBlock: `0x${to.toString(16)}`,
					topics: [TOPICS, pad(player)]
				}]
			});
			const out = [];
			for (const l of parseEventLogs({
				abi: fishingGameAbi,
				logs
			})) {
				if (l.address.toLowerCase() !== opts.game.toLowerCase() || l.blockNumber === null) continue;
				if (!("player" in l.args) || l.args.player.toLowerCase() !== player.toLowerCase()) continue;
				const at = {
					block: l.blockNumber,
					removed: !!l.removed
				};
				if (l.eventName === "Caught") out.push({
					...at,
					kind: "catch",
					fish: {
						id: l.args.fishId.toString(),
						speciesId: l.args.speciesId,
						weight: l.args.weight,
						locationId: l.args.locationId
					}
				});
				else if (l.eventName === "LocationUnlocked") out.push({
					...at,
					kind: "unlock",
					locationId: l.args.locationId
				});
				else if (l.eventName === "RodBought") out.push({
					...at,
					kind: "rod",
					rod: l.args.rod
				});
			}
			return out;
		},
		async player(player, block) {
			const p = await client.readContract({
				...game,
				functionName: "playerOf",
				args: [player],
				blockNumber: block
			});
			return {
				unlocks: p.unlocks,
				rods: p.rods
			};
		},
		async rewards(player, day, signer) {
			const [firstDay, claimed, signerAccepted] = await Promise.all([
				client.readContract({
					...rewards,
					functionName: "firstDay"
				}),
				client.readContract({
					...rewards,
					functionName: "claimed",
					args: [player, BigInt(day)]
				}),
				client.readContract({
					...rewards,
					functionName: "signers",
					args: [signer]
				})
			]);
			return {
				firstDay: Number(firstDay),
				claimed,
				signerAccepted
			};
		}
	};
}
